data.content:
Here are the MSTest comparison assertions you need for boundary checking:

| Assertion | Purpose |
|---|---|
| `Assert.IsGreaterThan(lowerBound, actual)` | Value exceeds a threshold |
| `Assert.IsLessThan(upperBound, actual)` | Value is below a limit |
| `Assert.IsInRange(actual, low, high)` | Value falls within [low, high] |

These give clear failure messages like *"Expected value to be greater than 0, but was -5"* — far better than `Assert.IsTrue(x > 0)`.

Here's a complete test class for your `ScoreCalculator`:

```csharp
using Contoso.Scoring;

namespace Contoso.Scoring.Tests;

[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calculator = new();

    // ── CalculatePercentage ──

    [TestMethod]
    [DataRow(5, 10, 50.0)]
    [DataRow(10, 10, 100.0)]
    [DataRow(0, 10, 0.0)]
    [DataRow(1, 3, 33.333333333333336)]
    public void CalculatePercentage_ValidInputs_ReturnsExpected(
        int correct, int total, double expected)
    {
        var result = _calculator.CalculatePercentage(correct, total);
        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void CalculatePercentage_Result_IsInValidRange()
    {
        var result = _calculator.CalculatePercentage(7, 10);

        Assert.IsGreaterThan(0.0, result);          // result > 0
        Assert.IsLessThan(100.0, result);            // result < 100 (not perfect)
        Assert.IsInRange(result, 0.0, 100.0);        // 0 ≤ result ≤ 100
    }

    [TestMethod]
    public void CalculatePercentage_PerfectScore_ReturnsExactly100()
    {
        var result = _calculator.CalculatePercentage(10, 10);
        Assert.AreEqual(100.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_ZeroCorrect_ReturnsZero()
    {
        var result = _calculator.CalculatePercentage(0, 10);
        Assert.AreEqual(0.0, result);
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(0, 0));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(11, 10));
    }

    // ── GetGrade boundary tests ──

    [TestMethod]
    [DataRow(90.0, "A")]
    [DataRow(100.0, "A")]
    [DataRow(89.9, "B")]
    [DataRow(80.0, "B")]
    [DataRow(79.9, "C")]
    [DataRow(70.0, "C")]
    [DataRow(69.9, "D")]
    [DataRow(60.0, "D")]
    [DataRow(59.9, "F")]
    [DataRow(0.0, "F")]
    public void GetGrade_AtBoundary_ReturnsCorrectGrade(
        double percentage, string expectedGrade)
    {
        var grade = _calculator.GetGrade(percentage);
        Assert.AreEqual(expectedGrade, grade);
    }

    // ── NormalizeScore ──

    [TestMethod]
    public void NormalizeScore_MidRange_IsInExpectedRange()
    {
        var result = _calculator.NormalizeScore(45.0, 100.0);

        Assert.IsGreaterThan(0.0, result);
        Assert.IsInRange(result, 0.0, 100.0);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_ClampedTo100()
    {
        var result = _calculator.NormalizeScore(120.0, 100.0);
        Assert.AreEqual(100.0, result);
    }

    [TestMethod]
    [DataRow(50.0, 100.0, 50.0)]
    [DataRow(0.0, 100.0, 0.0)]
    [DataRow(100.0, 100.0, 100.0)]
    [DataRow(25.0, 50.0, 50.0)]
    public void NormalizeScore_ValidInputs_ReturnsExpected(
        double raw, double maxRaw, double expected)
    {
        var result = _calculator.NormalizeScore(raw, maxRaw);
        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void NormalizeScore_NegativeRaw_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(-1.0, 100.0));
    }

    [TestMethod]
    public void NormalizeScore_ZeroMax_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(50.0, 0.0));
    }
}
```

**Key takeaways:**

- **`Assert.IsInRange(actual, low, high)`** — perfect for validating scores stay within 0–100
- **`Assert.IsGreaterThan(bound, actual)`** — verifies a score exceeds a minimum
- **`Assert.IsLessThan(bound, actual)`** — verifies a score stays below a cap
- **`Assert.ThrowsExactly<T>`** — validates guard clauses throw on invalid input
- **`[DataRow]`** on boundary values (90, 80, 70, 60 and just below each) catches off-by-one errors in `GetGrade`

All three comparison assertions require **MSTest 3.8+**. Use `[DataRow]` with boundary values at each grade threshold to ensure the `switch` expression's `>=` checks are correct.
